<script setup>import {reactive,ref} from 'vue';import {state,actions} from '../../domain/prototypeStore.js';const form=reactive({name:'',type:'现场处置',version:'v1.0',tasks:[{title:'现场核查',group:'现场处置组',deadline:'30分钟'}]}),msg=ref('');const save=()=>{const r=actions.savePlan(form);msg.value=r.message||(r.ok?'预案已保存':'操作失败')}</script>
<template><section class="page-stack"><div class="page-heading"><div class="module-icon">案</div><div><h2>应急预案</h2><p>维护预案版本和处置任务模板</p></div></div><article class="panel"><h3>新建演示预案</h3><div class="button-row"><input v-model="form.name" placeholder="预案名称"><select v-model="form.type"><option>现场处置</option><option>专项预案</option><option>综合预案</option></select><input v-model="form.tasks[0].title" placeholder="任务名称"><select v-model="form.tasks[0].group"><option>现场处置组</option><option>安全保障组</option></select><input v-model="form.tasks[0].deadline" placeholder="时限"><button class="primary-button active" @click="save">保存预案</button></div></article><p v-if="msg" class="action-message">{{msg}}</p><div class="card-grid"><article v-for="p in state.plans" :key="p.id" class="panel"><header><div><h3>{{p.name}}</h3><small>{{p.type}} · {{p.version}}</small></div><strong>{{p.status}}</strong></header><ol><li v-for="t in p.tasks" :key="t.title">{{t.title}} · {{t.group}} · {{t.deadline}}</li></ol><button class="secondary-button" @click="actions.togglePlan(p.id)">{{p.status==='已发布'?'停用':'发布'}}</button></article></div></section></template>
